package com.shopsphere;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;class NotFoundException extends RuntimeException{NotFoundException(String m){super(m);}}class ConflictException extends RuntimeException{ConflictException(String m){super(m);}}record ApiError(Instant timestamp,int status,String error,String message,String path,Map<String,String> validationErrors){}@RestControllerAdvice class Errors{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError> valid(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String>v=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->v.putIfAbsent(x.getField(),x.getDefaultMessage()));return out(HttpStatus.BAD_REQUEST,"Validation failed",r,v);}@ExceptionHandler(NotFoundException.class)ResponseEntity<ApiError> missing(NotFoundException e,HttpServletRequest r){return out(HttpStatus.NOT_FOUND,e.getMessage(),r,Map.of());}@ExceptionHandler(ConflictException.class)ResponseEntity<ApiError> conflict(ConflictException e,HttpServletRequest r){return out(HttpStatus.CONFLICT,e.getMessage(),r,Map.of());}private ResponseEntity<ApiError>out(HttpStatus s,String m,HttpServletRequest r,Map<String,String>v){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI(),v));}}
